const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  depserverUrl: 'http://mdm-depserver.mdm.svc.cluster.local:9001',
  scepUrl: 'http://mdm-scep.mdm.svc.cluster.local:8080',
  publicHost: 'mdm-prod.pke-lab.de',
  depName: 'capulus',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  vmUrl: 'http://vmsingle-monitoring-victoria-metrics-k8s-stack.monitoring.svc.cluster.local:8428',
  n8nUrl: 'https://n8n.prod.homeserver'
};
return [{ json: cfg }];

const input = $('Formular App').first().json;
const choice = String(input['App'] || '');
const idField = String(input['App-Store-ID oder Link (nur bei Andere App)'] || '').trim();
const serial = String(input['Seriennummer (leer = alle iPads)'] || '').trim();
const fail = (text) => [{ json: { ok: false, title: 'Nichts installiert', message: text } }];
if (serial.length > 40 || !/^[A-Za-z0-9]*$/.test(serial)) return fail('Die Seriennummer darf nur Buchstaben und Ziffern enthalten.');
if (choice === 'Andere App (ID unten)') {
  const match = /(?:id)?(\d{6,12})/.exec(idField);
  if (!match) return fail('Bitte die App-Store-ID (Ziffern) oder den App-Store-Link eintragen.');
  return [{ json: { ok: true, mode: 'other', adamId: match[1], serial } }];
}
if (choice === 'Alle Apps der Liste') return [{ json: { ok: true, mode: 'all', serial } }];
return [{ json: { ok: true, mode: 'one', appName: choice, serial } }];

const adamId = $('Eingabe pruefen').first().json.adamId;
const res = $input.first().json;
const raw = res.data !== undefined ? res.data : res.body;
let body = {};
try {
  body = typeof raw === 'string' ? JSON.parse(raw || '{}') : (raw || {});
} catch (e) {
  body = {};
}
const hit = (body.results || [])[0];
const fail = (text) => [{ json: { ok: false, title: 'Nichts installiert', message: text } }];
if (!hit) return fail('Im App Store (Deutschland) gibt es keine App mit der ID ' + adamId + '.');
if (hit.kind !== 'software' || !hit.bundleId) return fail('Die ID ' + adamId + ' ist keine iOS-App.');
if (!(hit.supportedDevices || []).some((device) => /iPad/.test(device))) return fail(hit.trackName + ' laeuft nicht auf iPads.');
if (Number(hit.price) > 0) return fail(hit.trackName + ' kostet Geld (' + hit.formattedPrice + '). Bezahlte Apps muessen in Apple Business gekauft werden, dieser Workflow installiert nur kostenlose Apps.');
return [{ json: { ok: true, adamId: String(hit.trackId), name: hit.trackName, bundleId: hit.bundleId } }];

const input = $('Eingabe pruefen').first().json;
const catalog = $input.all().map((item) => item.json).filter((row) => row.adam_id);
let apps = catalog;
if (input.mode === 'one') apps = catalog.filter((row) => row.name === input.appName);
if (input.mode === 'other') apps = catalog.filter((row) => row.adam_id === input.adamId);
if (apps.length === 0) return [{ json: { ok: false, title: 'Nichts installiert', message: 'Die App steht nicht in der Liste.' } }];
return [{ json: { ok: true, apps: apps.map((row) => ({ adamId: row.adam_id, name: row.name, bundleId: row.bundle_id })) } }];

const input = $('Eingabe pruefen').first().json;
const apps = $('Auswahl bestimmen').first().json.apps;
const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (devices.length === 0) return [{ json: { skip: true } }];
const serials = devices.map((row) => row.serial_number).filter(Boolean);
return [{ json: { skip: false, body: JSON.stringify({ assets: apps.map((app) => ({ adamId: app.adamId, pricingParam: 'STDQ' })), serialNumbers: serials }) } }];

const license = $('Lizenz zuweisen').first().json;
const apps = $('Auswahl bestimmen').first().json.apps;
const sent = $('Befehle bauen').all().map((item) => item.json);
const results = $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  return { serial: source.serial_number || source.enrollment_id, app: source.app, queued, detail: queued ? '' : String(response.json.statusCode || response.json.error || 'keine Antwort') };
});
const ok = results.filter((row) => row.queued);
const failed = results.filter((row) => !row.queued);
const lines = [];
const licenseBody = license.body || {};
const names = apps.map((app) => app.name).join(', ');
if (license.statusCode === 200) {
  lines.push('Lizenz fuer ' + names + ' wurde zugewiesen.');
} else {
  lines.push('ACHTUNG: Die Lizenzzuweisung bei Apple schlug fehl (HTTP ' + (license.statusCode || license.error || 'keine Antwort') + (licenseBody.errorMessage ? ', ' + licenseBody.errorMessage : '') + '). Ohne Lizenz kann ein iPad ohne Apple-ID die App nicht installieren.');
}
lines.push(ok.length + ' von ' + results.length + ' Installationsbefehl(en) eingereiht.');
if (failed.length > 0) lines.push('Nicht eingereiht: ' + failed.map((row) => row.serial + '/' + row.app + ' (' + row.detail + ')').join(', ') + '.');
const good = license.statusCode === 200 && failed.length === 0;
return [{ json: { good, names, text: lines.join(' ') } }];

const crypto = require('crypto');
const claimed = $input.all().map((item) => item.json).filter((row) => row.profile_name);
if (claimed.length === 0) return [{ json: { skip: true } }];
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
return claimed.map((row) => {
  const params = typeof row.params === 'string' ? JSON.parse(row.params) : row.params;
  let profile = row.template;
  for (const [key, value] of Object.entries(params)) {
    const text = Array.isArray(value)
      ? value.map((item) => '\t\t\t\t<string>' + escapeXml(item) + '</string>').join('\n')
      : escapeXml(value);
    profile = profile.split('__' + key + '__').join(text);
  }
  profile = profile.split('__VERSION__').join(String(row.version));
  const commandUuid = crypto.randomUUID();
  const plist = '<?xml version="1.0" encoding="UTF-8"?>\n'
    + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
    + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n\t\t<key>Payload</key>\n\t\t<data>'
    + Buffer.from(profile, 'utf8').toString('base64')
    + '</data>\n\t\t<key>RequestType</key>\n\t\t<string>InstallProfile</string>\n\t</dict>\n\t<key>CommandUUID</key>\n\t<string>'
    + commandUuid + '</string>\n</dict>\n</plist>\n';
  return { json: { skip: false, enrollment_id: row.enrollment_id, profile_name: row.profile_name, version: row.version, command_uuid: commandUuid, plist } };
});

const sent = $('Liste Befehle bauen').all().map((item) => item.json).filter((row) => !row.skip);
return $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  const results = Object.values(body.status || {});
  const pushError = results.map((entry) => entry.push_error).filter(Boolean).join('; ');
  const detail = queued ? pushError : String(response.json.statusCode || response.json.error || 'keine Antwort');
  return { json: { enrollment_id: source.enrollment_id, profile_name: source.profile_name, command_uuid: source.command_uuid, ok: queued ? 'yes' : 'no', detail } };
});

const install = $('Ergebnis auswerten').first().json;
let listLine = 'Die Erlaubt-Liste ist unveraendert.';
const sentRows = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (sentRows.length > 0) {
  const failed = sentRows.filter((row) => row.state === 'failed');
  listLine = 'Die Erlaubt-Liste wurde an ' + (sentRows.length - failed.length) + ' von ' + sentRows.length + ' iPad(s) gesendet' + (failed.length > 0 ? ', ' + failed.length + ' fehlgeschlagen' : '') + '.';
}
return [{ json: { title: install.good ? install.names + ' wird installiert' : 'Installation mit Problemen: ' + install.names, message: install.text + ' ' + listLine + ' Die Liste greift nur auf beaufsichtigten iPads.', priority: install.good ? 'default' : 'high' } }];
